using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using Unity.XR.CoreUtils;using LighthouseKeepers.WatchDemo;
public static class WallSweep {
 static IEnumerator loop;static CustomYieldInstruction wait;static string output;static int frame;static double deadline;static List<string> log=new();
 public static object Run(string folder){output=folder;Directory.CreateDirectory(folder);loop=Replay();deadline=EditorApplication.timeSinceStartup+240;EditorApplication.update+=Tick;return true;}
 static void Tick(){if(frame==Time.frameCount||(wait!=null&&wait.keepWaiting))return;frame=Time.frameCount;try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("capture timeout");if(loop.MoveNext()){wait=loop.Current as CustomYieldInstruction;return;}Finish();}catch(Exception e){log.Add("FAIL "+e);Finish();}}
 static void Finish(){File.WriteAllLines(output+"/result.txt",log);EditorApplication.update-=Tick;EditorApplication.isPlaying=false;}
 static IEnumerator Replay(){GameObject.Find("PlaySolo").GetComponent<Button>().onClick.Invoke();WatchDemoController w=null;while(!(w=UnityEngine.Object.FindAnyObjectByType<WatchDemoController>()))yield return null;yield return new WaitForSecondsRealtime(6);var camera=Camera.main;var rig=UnityEngine.Object.FindAnyObjectByType<XROrigin>();foreach(var c in rig.GetComponents<MonoBehaviour>())if(c.GetType().Name=="DesktopPreview")c.enabled=false;
  var positions=new[]{new Vector3(-.9f,1.65f,-8.4f),new Vector3(0,1.65f,0),new Vector3(0,4.95f,0),new Vector3(0,8.25f,0),new Vector3(0,11.55f,0),new Vector3(-2,3,1.8f),new Vector3(-2,6,1.8f),new Vector3(-1,9,1),new Vector3(0,11.55f,-3.8f)};
  for(int floor=0;floor<positions.Length;floor++)for(int angle=0;angle<8;angle++){camera.transform.SetPositionAndRotation(positions[floor],Quaternion.Euler(0,angle*45,0));yield return null;Capture(camera,output+"/sweep-"+floor+"-"+angle+".png");}
  foreach(var r in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))if(r.name.StartsWith("SM_Wall")&&r.enabled){foreach(var m in r.sharedMaterials)if(m&&m.HasProperty("_Cull")&&m.GetFloat("_Cull")!=0)throw new Exception("Backface culling still active: "+r.name);}
  log.Add("PASS 72 rendered sweep views: House, four floors, three stair flights, gallery; wall materials double-sided opaque; camera clip .04; occlusion off.");
  log.Add("camera near="+camera.nearClipPlane+" occlusion="+camera.useOcclusionCulling);log.Add("TMP HUD labels="+UnityEngine.Object.FindObjectsByType<TMPro.TextMeshProUGUI>(FindObjectsSortMode.None).Length);foreach(var l in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None))log.Add("LIGHT "+l.name+" enabled="+l.enabled+" bake="+l.lightmapBakeType+" shadows="+l.shadows);log.Add("PASS graphics capture completed; inspect images separately");
 }
 static void Capture(Camera camera,string path){var target=new RenderTexture(640,480,24);var old=camera.targetTexture;var active=RenderTexture.active;try{camera.targetTexture=target;camera.Render();RenderTexture.active=target;var image=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{camera.targetTexture=old;RenderTexture.active=active;target.Release();UnityEngine.Object.DestroyImmediate(target);}}
}
